/** Waterfall steps for Big-5 vintage revision (Q3 ??? 202608) */
export function waterfallSteps(active: Hyperscaler[] = [...HYPERSCALERS]) {
  const deltas = companyDeltas(active);
  const priorSum = Math.round(deltas.reduce((s, d) => s + d.priorBn, 0) * 10) / 10;
  const steps: {
    name: string;
    start: number;
    end: number;
    delta: number;
    fill: string;
    kind: "base" | "delta" | "total";
  }[] = [
    {
      name: "Q3 Big-5",
      start: 0,
      end: priorSum,
      delta: priorSum,
      fill: "#64748b",
      kind: "base",
    },
  ];
  let running = priorSum;
  for (const d of deltas) {
    const next = Math.round((running + d.deltaBn) * 10) / 10;
    steps.push({
      name: d.company,
      start: Math.min(running, next),
      end: Math.max(running, next),
      delta: d.deltaBn,
      fill: d.fill,
      kind: "delta",
    });
    running = next;
  }
  steps.push({
    name: "Aug-20 Big-5",
    start: 0,
    end: running,
    delta: running,
    fill: "#10b981",
    kind: "total",
  });
  return { steps, priorSum, newSum: running };
}

