"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  LineChart,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  CONCENTRATION_PATH,
  HEADLINE,
  MSFT_SENSITIVITY,
  PERIMETER_STACKS,
  POSITIVE_RAISE_SLICES,
  RAISE_ROWS,
  SHARE_LADDER_AUG20,
  SOURCE_NOTE,
  SOURCES,
  YEAR_LABELS,
  companyShares,
  concentrationCurve,
  concentrationMetrics,
  fmtBn,
  fmtHhi,
  fmtPct,
  type CapexYearKey,
} from "@/data/ai-capex-spend-concentration-202608-data";

// viz-types: Lorenz area+line, ranked share bars, raise donut, path multi-line, perimeter bars, share-dollar scatter | layout: default

type ViewId = "ladder" | "path" | "raises" | "perimeters";

const TEAL = "#0d9488";
const AMBER = "#f59e0b";
const SKY = "#0ea5e9";
const VIOLET = "#8b5cf6";
const SLATE = "#64748b";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle && <p className="mt-1 text-sm text-slate-500">{subtitle}</p>}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ToggleGroup<T extends string>({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: T;
  options: { id: T; label: string }[];
  onChange: (v: T) => void;
}) {
  return (
    <div className="flex flex-wrap items-center gap-2">
      <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
        {label}
      </span>
      <div className="flex flex-wrap gap-1">
        {options.map((o) => (
          <button
            key={o.id}
            type="button"
            onClick={() => onChange(o.id)}
            className={`rounded-md px-3 py-1.5 text-sm font-medium transition-colors ${
              value === o.id
                ? "bg-slate-900 text-white"
                : "bg-slate-100 text-slate-700 hover:bg-slate-200"
            }`}
          >
            {o.label}
          </button>
        ))}
      </div>
    </div>
  );
}

export function AiCapexSpendConcentration202608Dashboard() {
  const [view, setView] = useState<ViewId>("ladder");
  const [year, setYear] = useState<CapexYearKey>("2026-aug20");
  const [aiOnly, setAiOnly] = useState(false);
  const [msftMode, setMsftMode] = useState<"accounting" | "economic">(
    "accounting",
  );

  const metrics = useMemo(() => concentrationMetrics(year), [year]);
  const curve = useMemo(() => concentrationCurve(year), [year]);
  const shares = useMemo(() => companyShares(year, aiOnly), [year, aiOnly]);
  const scatterData = useMemo(
    () =>
      shares.map((s) => ({
        company: s.company,
        bn: s.bn,
        sharePct: s.sharePct,
        fill: s.fill,
      })),
    [shares],
  );

  const sensitivity = MSFT_SENSITIVITY.find((s) => s.id === msftMode)!;
  const useSensitivity = year === "2026-aug20";

  return (
    <div
      className="space-y-6"
      data-viz="ai-capex-spend-concentration-202608"
    >
      <div className="rounded-xl border border-amber-200 bg-amber-50/80 px-5 py-4">
        <p className="text-sm font-semibold text-amber-950">
          AI capex & spend ??? late-Aug 202608 concentration lens
        </p>
        <p className="mt-1 text-sm text-amber-900/80">
          Top-1 holds {fmtPct(HEADLINE.top1SharePct)} ({HEADLINE.top1Label},{" "}
          {fmtBn(HEADLINE.top1Bn)}); top-3 holds {fmtPct(HEADLINE.top3SharePct)}{" "}
          of the late-Aug Big-5 stack ({fmtBn(HEADLINE.big5TotalBn)}). HHI ???{" "}
          {fmtHhi(HEADLINE.hhi)}.
        </p>
      </div>

      <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center sm:justify-between">
        <ToggleGroup
          label="View"
          value={view}
          options={[
            { id: "ladder", label: "Concentration ladder" },
            { id: "path", label: "Multi-year path" },
            { id: "raises", label: "Raise concentration" },
            { id: "perimeters", label: "Perimeters" },
          ]}
          onChange={setView}
        />
        <ToggleGroup
          label="Vintage"
          value={year}
          options={[
            { id: "2024", label: "2024" },
            { id: "2025", label: "2025" },
            { id: "2026-jul", label: "Jul research" },
            { id: "2026-aug", label: "Aug post-Q2" },
            { id: "2026-q3", label: "Mid-Q3" },
            { id: "2026-aug20", label: "Late-Aug" },
          ]}
          onChange={setYear}
        />
      </div>

      {view === "ladder" && (
        <>
          <div className="flex flex-wrap gap-3">
            <ToggleGroup
              label="Perimeter"
              value={aiOnly ? "ai" : "gross"}
