                  <Tooltip />
                  <Bar
                    yAxisId="left"
                    dataKey="totalBn"
                    fill={SKY}
                    fillOpacity={0.7}
                    name="Big-5 total"
                    radius={[4, 4, 0, 0]}
                  />
                  <Line
                    yAxisId="right"
                    type="monotone"
                    dataKey="top1Pct"
                    stroke={AMBER}
                    strokeWidth={2.5}
                    name="Top-1 %"
                  />
                </ComposedChart>
              </ResponsiveContainer>
