          </ChartCard>
        </div>
      )}

      {view === "raises" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="Who captured the Q3???Aug20 raises"
            subtitle={`Positive dollar raises sum to $${POSITIVE_RAISE_SLICES.reduce((s, r) => s + r.deltaBn, 0)}B; Amazon+Alphabet = ${fmtPct(HEADLINE.top2RaiseSharePct)}`}
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={POSITIVE_RAISE_SLICES}
                    dataKey="deltaBn"
                    nameKey="company"
                    cx="50%"
                    cy="50%"
                    innerRadius={55}
                    outerRadius={95}
                    paddingAngle={2}
                  >
                    {POSITIVE_RAISE_SLICES.map((s) => (
                      <Cell key={s.company} fill={s.fill} />
                    ))}
                  </Pie>
                  <Tooltip
                    formatter={(v, _n, p) => [
                      `${fmtBn(Number(v))} (${fmtPct((p?.payload as { sharePct: number })?.sharePct ?? 0)})`,
                      "Raise",
                    ]}
                  />
                </PieChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Company ?? Aug post-Q2 ??? mid-Q3"
            subtitle="Microsoft???s accounting print is flat ??? lease reclass still the economic story"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={RAISE_ROWS}
                  margin={{ top: 8, right: 12, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="company" tick={{ fontSize: 11 }} />
                  <YAxis
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v > 0 ? "+" : ""}${v}`}
                  />
                  <Tooltip
                    formatter={(v) => {
                      const n = Number(v);
                      return [`${n > 0 ? "+" : ""}${fmtBn(n)}`, "??"];
                    }}
                  />
                  <Bar dataKey="deltaBn" radius={[4, 4, 0, 0]}>
                    {RAISE_ROWS.map((r) => (
                      <Cell
                        key={r.company}
                        fill={r.deltaBn > 0 ? r.fill : SLATE}
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      {view === "perimeters" && (
        <div className="grid gap-6 lg:grid-cols-2">
          <ChartCard
            title="2026 stacks by research perimeter"
            subtitle="Do not mix scopes ??? company shares only apply inside Big-5 gross"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={PERIMETER_STACKS}
                  margin={{ top: 8, right: 12, left: 0, bottom: 48 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis
                    dataKey="label"
                    tick={{ fontSize: 10 }}
                    interval={0}
                    angle={-25}
                    textAnchor="end"
                    height={60}
                  />
                  <YAxis
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `$${v}B`}
                  />
                  <Tooltip
                    formatter={(v) => [fmtBn(Number(v)), "2026"]}
                    labelFormatter={(_, p) =>
                      (p?.[0]?.payload as { scope?: string })?.scope ?? ""
                    }
                  />
                  <Bar dataKey="bn2026" radius={[4, 4, 0, 0]}>
                    {PERIMETER_STACKS.map((r) => (
                      <Cell key={r.id} fill={r.color} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>

          <ChartCard
            title="Microsoft accounting vs economic sensitivity"
            subtitle="Lease reclass shifts share math without changing campus spend"
          >
            <div className="h-72 w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={[...MSFT_SENSITIVITY]}
                  margin={{ top: 8, right: 12, left: 0, bottom: 8 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                  <XAxis dataKey="label" tick={{ fontSize: 10 }} />
                  <YAxis
                    tick={{ fontSize: 11 }}
                    tickFormatter={(v) => `${v}%`}
                    domain={[20, 80]}
                  />
                  <Tooltip formatter={(v) => [fmtPct(Number(v)), ""]} />
                  <Bar
                    dataKey="top1Pct"
                    fill={AMBER}
                    name="Top-1 %"
                    radius={[4, 4, 0, 0]}
                  />
                  <Bar
                    dataKey="top3Pct"
                    fill={TEAL}
                    name="Top-3 %"
                    radius={[4, 4, 0, 0]}
                  />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      )}

      <p className="text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
      <p className="text-xs text-slate-500">
        Sources:{" "}
        {SOURCES.map((s, i) => (
          <span key={s.url}>
            {i > 0 && " ?? "}
            <a href={s.url} className="underline hover:text-slate-700">
              {s.label}
            </a>
          </span>
        ))}
      </p>
    </div>
  );
}

